import{_ as a,o as e,c as r,a4 as o}from"./chunks/framework.D-V5jUSB.js";const _=JSON.parse('{"title":"可解釋結果","description":"","frontmatter":{},"headers":[],"relativePath":"explainable.md","filePath":"explainable.md"}'),n={name:"explainable.md"};function l(i,t,d,s,p,h){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="可解釋結果" tabindex="-1">可解釋結果 <a class="header-anchor" href="#可解釋結果" aria-label="Permalink to &quot;可解釋結果&quot;">​</a></h1><p>AI 找到片時,不能只丟一個結果就算了 —— 要講得出<strong>為什麼是這部片</strong>。 這個原型的每張結果卡都帶一行「說明」,編輯一眼就知道該不該信,也能跟同事解釋為什麼推這部。</p><h2 id="結果卡上的那行字" tabindex="-1">結果卡上的那行字 <a class="header-anchor" href="#結果卡上的那行字" aria-label="Permalink to &quot;結果卡上的那行字&quot;">​</a></h2><blockquote><p><code>符合 [音樂][美式] · 語意+推想+字面</code></p></blockquote><p>拆成兩半看:</p><p><strong>前半 — 對上你哪些條件</strong>:<code>[音樂][美式]</code> 是這部片同時命中了你查詢裡的哪幾個維度 (例如曲風、地區)。沒對上的維度不會硬掛上去。</p><p><strong>後半 — 它是怎麼被找到的</strong>:三種來源,可能同時出現:</p><table tabindex="0"><thead><tr><th>標記</th><th>意思</th></tr></thead><tbody><tr><td>語意</td><td>意思相近被撈到(就算用字不一樣)</td></tr><tr><td>推想</td><td>AI 先想像「最符合的片長什麼樣」,這部命中了那個想像</td></tr><tr><td>字面</td><td>查詢字詞直接出現在片名 / 劇情裡</td></tr></tbody></table><h2 id="為什麼這對編輯有用" tabindex="-1">為什麼這對編輯有用 <a class="header-anchor" href="#為什麼這對編輯有用" aria-label="Permalink to &quot;為什麼這對編輯有用&quot;">​</a></h2><ul><li><strong>判斷該不該信</strong>:看到「只靠推想、沒對到任何條件」,就知道要存疑。</li><li><strong>講得出口</strong>:跟主管解釋「為什麼推這部」時有具體依據,不是「系統說的」。</li><li><strong>抓問題</strong>:結果怪怪的時候,這行字直接指出是哪一路出包(見 <a href="/film-brain/vp-preview/mj-case">除錯實錄</a>)。</li></ul><hr><p>延伸:標籤怎麼防 AI 亂編、編輯怎麼把關 → <a href="/film-brain/vp-preview/auto-tag">自動標籤</a>; 查不到時怎麼誠實處理 → <a href="/film-brain/vp-preview/honest">誠實匹配</a>。</p>',12)])])}const b=a(n,[["render",l]]);export{_ as __pageData,b as default};
